package com.fakenewsdetector.controller;
import com.fakenewsdetector.entity.User; import com.fakenewsdetector.service.PredictionService; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid;
@RestController public class PredictionController {record Request(@NotBlank(message="News text is required.")@Size(min=20,max=50000)String text){} private final PredictionService service;public PredictionController(PredictionService s){service=s;}@PostMapping("/api/predict")public Map<String,Object> predict(@AuthenticationPrincipal User u,@Valid @RequestBody Request r){return Map.of("success",true,"data",service.predict(u,r.text()));}}
